def lin(n,f,A,kind='plane'):
 vals=dict(zip([x,y],A));f0=s.simplify(f.subs(vals));grad=[s.simplify(s.diff(f,j).subs(vals)) for j in [x,y]];expr=s.simplify(f0+grad[0]*(x-A[0])+grad[1]*(y-A[1]));
 ko='접평면을 구하라.' if kind=='plane' else '미분 가능성을 설명하고 선형화를 구하라.';en='Find the tangent plane.' if kind=='plane' else 'Explain differentiability and find the linearization.'
 if kind=='graph':ko='곡면과 접평면을 함께 그리고 확대하여 비교하라.';en='Plot the surface and tangent plane together and compare them after zooming in.'
 st=(f'함수 \\(f={L(f)}\\), 기준점 \\({L(s.Tuple(*A))}\\). '+ko,f'For \\(f={L(f)}\\) at \\({L(s.Tuple(*A))}\\), '+en)
 sk=[f'기준점 함수값은 \\({L(f0)}\\); 두 편도함수는 \\(f_x={L(s.diff(f,x))},f_y={L(s.diff(f,y))}\\).',f'기준점 기울기는 \\({L(s.Tuple(*grad))}\\). \\(L=f(a,b)+f_x(a,b)(x-a)+f_y(a,b)(y-b)\\)에 대입한다.'];se=[f'The base value is \\({L(f0)}\\); the derivatives are \\(f_x={L(s.diff(f,x))},f_y={L(s.diff(f,y))}\\).',f'The gradient at the base point is \\({L(s.Tuple(*grad))}\\). Substitute into \\(L=f(a,b)+f_x(a,b)(x-a)+f_y(a,b)(y-b)\\).']
 if kind!='plane':sk.insert(0,'이 점의 충분히 작은 근방에서는 분모가 0이 아니고 로그·제곱근·삼각함수의 미분 조건을 충족한다. 두 편도함수가 연속이므로 미분 가능하다.');se.insert(0,'On a sufficiently small neighborhood, denominators are nonzero and logarithm, square-root, and trigonometric domains allow continuous first partials. Thus the function is differentiable.')
 if kind=='graph':sk.append('오차는 거리의 제곱 수준이므로 같은 축척으로 확대할수록 곡면과 평면이 가까워진다.');se.append('The error is quadratic in displacement, so the surface approaches the plane under equal-scale magnification.')
 answer=f'\\({"z" if kind in ["plane","graph"] else "L(x,y)"}={L(expr)}\\).'
 add(n,st,sk,se,answer,answer,'선형식은 기준점의 함수값과 두 편도함수를 모두 보존한다.','The linear formula matches the function value and both first partials at the base point.')
 return (f,A,expr)
