add(27,(r'\(f=\sqrt{x^2+y^2+z^2}\)를 (3,2,6)에서 선형화하여 \(\sqrt{3.02^2+1.97^2+5.99^2}\)를 추정하라.',r'Linearize \(f=\sqrt{x^2+y^2+z^2}\) at (3,2,6) to estimate \(\sqrt{3.02^2+1.97^2+5.99^2}\).'),[r'f0=7, ∇f=(3,2,6)/7.',r'\(L=7+[3(x-3)+2(y-2)+6(z-6)]/7\). 변위 (0.02,−0.03,−0.01)를 넣는다.'],[r'f0=7, ∇f=(3,2,6)/7.',r'\(L=7+[3(x-3)+2(y-2)+6(z-6)]/7\). Insert (0.02,−0.03,−0.01).'],r'\(L=7+[3(x-3)+2(y-2)+6(z-6)]/7\), 약 6.99143.',r'\(L=7+[3(x-3)+2(y-2)+6(z-6)]/7\), approximately 6.99143.','변위와 단위 방사벡터의 내적이 −0.06/7이다.','The displacement dotted with the radial unit vector is −0.06/7.')
add(28,('풍속 v(knots), 지속시간 t(hours)의 파고 h(ft) 표에서 t=5,10,15,20,30,40,50 열에 대한 행 v=20:5,7,8,8,9,9,9; v=30:9,13,16,17,18,19,19; v=40:14,21,25,28,31,33,33; v=50:19,29,36,40,45,48,50; v=60:24,37,47,54,62,67,69이다. (40,20) 근방 선형식과 (43,24)의 파고를 구하라.','The wave-height h(ft) table has t(hours)=5,10,15,20,30,40,50 columns. Rows v(knots):20:5,7,8,8,9,9,9;30:9,13,16,17,18,19,19;40:14,21,25,28,31,33,33;50:19,29,36,40,45,48,50;60:24,37,47,54,62,67,69. Linearize near (40,20) and estimate at (43,24).'),['대칭 차분 hv≈(40−17)/20=1.15. t=10,30의 대칭 표본으로 ht≈(31−21)/20=0.5.','L=28+1.15(v−40)+0.5(t−20)에 (43,24)를 넣는다.'],['Centered differences give hv≈(40−17)/20=1.15 and ht≈(31−21)/20=0.5 using symmetric t=10,30 samples.','Substitute (43,24) into L=28+1.15(v−40)+0.5(t−20).'],'L=28+1.15(v−40)+0.5(t−20), 약 33.45 ft.','L=28+1.15(v−40)+0.5(t−20), approximately 33.45 ft.','표 기반 기울기 근사라 선택한 차분에 따라 추정값이 조금 달라질 수 있다.','Finite-difference choices can slightly change this table-based estimate.')
add(29,('예제3의 열지수 표에서 I(94,80)=127, I(92,80)=119, I(96,80)=135, I(94,75)=122, I(94,85)=132(°F)이다. T=94°F,H=80% 근방에서 선형화하고 (95,78)의 지수를 추정하라.','The Example3 heat-index table gives I(94,80)=127, I(92,80)=119, I(96,80)=135, I(94,75)=122, I(94,85)=132 (°F). Linearize at (94°F,80%) and estimate I(95,78).'),['IT≈(135−119)/4=4, IH≈(132−122)/10=1.','L=127+4(T−94)+(H−80).'],['IT≈(135−119)/4=4, IH≈(132−122)/10=1.','L=127+4(T−94)+(H−80).'],'L=127+4(T−94)+(H−80), 약129°F.','L=127+4(T−94)+(H−80), approximately129°F.','온도+1°F와 습도−2%가 각각+4,−2°F를 기여한다.','The +1°F and −2 percentage-point changes contribute +4 and −2°F.')
add(30,('풍랭 표의 W(−15,50)=−29, W(−10,50)=−22, W(−20,50)=−35, W(−15,40)=−27, W(−15,60)=−30이다. T(°C),v(km/h)의 (−15,50) 근방 선형식으로 W(−17,55)를 추정하라.','The wind-chill table gives W(−15,50)=−29, W(−10,50)=−22, W(−20,50)=−35, W(−15,40)=−27, W(−15,60)=−30. Linearize in T(°C),v(km/h) at (−15,50) and estimate W(−17,55).'),['WT≈13/10=1.3, Wv≈−3/20=−0.15.','L=−29+1.3(T+15)−0.15(v−50).'],['WT≈13/10=1.3, Wv≈−3/20=−0.15.','L=−29+1.3(T+15)−0.15(v−50).'],'약 −32.35°C.','Approximately −32.35°C.','온도가 내려가고 바람이 강해져 체감온도 두 기여가 모두 감소한다.','Lower temperature and stronger wind both decrease the perceived temperature.')
for n,name,f,vars in [(31,'m',p**5*q**3,[p,q]),(32,'z',x*s.log(y*y+1),[x,y]),(33,'z',s.exp(-2*x)*s.cos(2*s.pi*t),[x,t]),(34,'u',s.sqrt(x*x+3*y*y),[x,y]),(35,'H',x*x*y**4+y**3*z**5,[x,y,z]),(36,'w',x*z*s.exp(-y*y-z*z),[x,y,z]),(37,'R',a*b*b*s.cos(g),[a,b,g]),(38,'T',v/(1+u*v*w),[u,v,w])]:
 derivs=[s.diff(f,j) for j in vars];df='+'.join('('+L(d)+')\\,d'+L(j) for j,d in zip(vars,derivs));expr='\\(d'+name+'='+df+'\\)';add(n,(f'\\({name}={L(f)}\\)의 전미분을 구하라.',f'Find the differential of \\({name}={L(f)}\\).'),[r'전미분은 각 편도함수와 해당 변수 증분의 곱을 더한 것이다.',f'편도함수 벡터는 \\({L(s.Tuple(*derivs))}\\).'],['Sum each first partial derivative times the increment of its variable.',f'The derivative vector is \\({L(s.Tuple(*derivs))}\\).'],expr,expr,'연쇄법칙과 곱의 법칙으로 성분을 직접 검산했다.','Components were verified directly by the chain and product rules.')
for n,f,A,B in [(39,5*x*x+y*y,(1,2),(s.Rational(105,100),s.Rational(21,10))),(40,x*x-x*y+3*y*y,(3,-1),(s.Rational(296,100),-s.Rational(95,100)))]:
 va=dict(zip([x,y],A));vb=dict(zip([x,y],B));df=sum(s.diff(f,j).subs(va)*(bb-aa) for j,aa,bb in zip([x,y],A,B));dz=s.simplify(f.subs(vb)-f.subs(va));add(n,(f'\\(z={L(f)}\\), \\({L(s.Tuple(*A))}\\)에서 \\({L(s.Tuple(*B))}\\)로 변할 때 Δz와 dz를 비교하라.',f'For \\(z={L(f)}\\), compare Δz and dz for the change from \\({L(s.Tuple(*A))}\\) to \\({L(s.Tuple(*B))}\\).'),[f'실제 변화는 \\(\\Delta z=f(B)-f(A)={L(dz)}\\).',f'미분은 \\(dz=f_x(A)\\Delta x+f_y(A)\\Delta y={L(df)}\\).'],[f'The actual change is \\(\\Delta z=f(B)-f(A)={L(dz)}\\).',f'The differential is \\(dz=f_x(A)\\Delta x+f_y(A)\\Delta y={L(df)}\\).'],f'\\(\\Delta z={L(dz)},dz={L(df)}\\).',f'\\(\\Delta z={L(dz)},dz={L(df)}\\).',f'차이 \\({L(dz-df)}\\)는 이차항이다.',f'The difference \\({L(dz-df)}\\) is quadratic.')
apps=[(41,'직사각형의 길이30 cm, 폭24 cm를 각각 오차≤0.1 cm로 측정했다. 넓이의 최대오차를 미분으로 추정하라.','A rectangle measures30 cm by24 cm, each with error≤0.1 cm. Estimate maximum area error using differentials.',r'A=lw,\ dA=w\,dl+l\,dw',r'|dA|\le24(0.1)+30(0.1)=5.4','약5.4 cm².','Approximately5.4 cm².'),(42,'높이10 cm, 지름4 cm인 닫힌 원통의 옆면 두께0.05 cm, 위아래 두께0.1 cm일 때 금속 부피를 미분으로 추정하라.','Estimate metal volume in a closed cylinder10 cm high and4 cm in diameter, with wall thickness0.05 cm and each cap thickness0.1 cm.',r'V=\pi r^2h,\ dV=2\pi rh\,dr+\pi r^2dh',r'r=2,h=10,dr=0.05,dh=0.2:\quad dV=2.8\pi','약2.8π cm³.','Approximately2.8π cm³.'),(43,'지름8 cm, 높이12 cm인 닫힌 원통 깡통의 모든 두께가0.04 cm이다. 금속 부피를 미분으로 추정하라.','Estimate tin volume in a closed cylinder8 cm in diameter and12 cm high, with uniform thickness0.04 cm.',r'dV=2\pi rh\,dr+\pi r^2dh',r'r=4,h=12,dr=0.04,dh=0.08:\quad dV=5.12\pi','약5.12π cm³.','Approximately5.12π cm³.')]
for n,sk,se,eq,sub,ak,ae in apps:add(n,(sk,se),[f'기본 미분식은 \\({eq}\\).',f'주어진 값을 넣으면 \\({sub}\\).'],[f'The differential formula is \\({eq}\\).',f'Substitution gives \\({sub}\\).'],ak,ae,'작은 두께/오차의 곱인 고차항은 버린 1차 근사이다.','This first-order estimate omits products of small errors or thicknesses.')
add(44,('삼각형의 밑변28 in, 높이16 in, 각 측정오차≤ε in. (a) 넓이오차를 미분으로 추정하고 (b) ε=1/4일 때 계산하라.','A triangle has base28 in and height16 in, each with error≤ε in. (a) Estimate area error by differentials; (b) evaluate for ε=1/4.'),[r'\(A=bh/2\), \(|dA|\le(h/2+b/2)\epsilon=(8+14)\epsilon\).','ε=1/4를 대입하면22/4=5.5이다.'],[r'\(A=bh/2\), \(|dA|\le(h/2+b/2)\epsilon=(8+14)\epsilon\).','For ε=1/4 the result is22/4=5.5.'],'(a) 약22ε in². (b) 약5.5 in².','(a) About22ε in². (b) About5.5 in².','최대 1차오차는 두 기여의 절댓값 합이다.','The largest first-order error is the sum of absolute contributions.',['a','b'])
add(45,('원통 r=2.5 ft,h=12 ft의 각 측정오차≤ε ft. (a) 부피오차의 미분 추정, (b) 부피오차≤1 ft³를 위한 ε 한계를 구하라.','For a cylinder r=2.5 ft,h=12 ft with error≤ε ft in each dimension, (a) estimate volume error and (b) find ε for estimated error≤1 ft³.'),[r'\(|dV|\le(2\pi rh+\pi r^2)\epsilon=(265\pi/4)\epsilon\).',r'1차 기준 \((265\pi/4)\epsilon\le1\)을 푼다. 이는 실제 유한오차의 엄밀한 상한이 아니라 미분 근사이다.'],[r'\(|dV|\le(2\pi rh+\pi r^2)\epsilon=(265\pi/4)\epsilon\).',r'Solve the first-order condition \((265\pi/4)\epsilon\le1\). This is the differential estimate, not a rigorous bound for finite errors.'],r'(a) 약 \(265\pi\epsilon/4\) ft³. (b) \(\epsilon\le4/(265\pi)\approx0.004805\) ft.',r'(a) About \(265\pi\epsilon/4\) ft³. (b) \(\epsilon\le4/(265\pi)\approx0.004805\) ft.','단위는 부피 민감도(ft²)×길이오차(ft)이다.','Dimensions are volume sensitivity(ft²) times length error(ft).',['a','b'])
T,V=s.symbols('T V',positive=True);W=s.Rational(1312,100)+s.Rational(6215,10000)*T-s.Rational(1137,100)*V**s.Rational(16,100)+s.Rational(3965,10000)*T*V**s.Rational(16,100);WT=s.diff(W,T).subs({T:-11,V:26});WV=s.diff(W,V).subs({T:-11,V:26});err=float(WT-2*WV)
add(46,(r'\(W=13.12+0.6215T-11.37v^{0.16}+0.3965Tv^{0.16}\). T=−11±1°C,v=26±2 km/h의 측정오차가 만드는 최대 W오차를 추정하라.',r'For \(W=13.12+0.6215T-11.37v^{0.16}+0.3965Tv^{0.16}\), estimate maximum error from T=−11±1°C and v=26±2 km/h.'),[r'\(W_T=0.6215+0.3965v^{0.16}\), \(W_v=0.16(-11.37+0.3965T)v^{-0.84}\).',f'주어진 점에서 WT≈{float(WT):.6f}, Wv≈{float(WV):.6f}. 최대오차는 |WT|×1+|Wv|×2.'],[r'\(W_T=0.6215+0.3965v^{0.16}\), \(W_v=0.16(-11.37+0.3965T)v^{-0.84}\).',f'At the stated point WT≈{float(WT):.6f}, Wv≈{float(WV):.6f}. Maximum error is |WT|×1+|Wv|×2.'],f'약{err:.4f}°C.',f'Approximately{err:.4f}°C.','온도 기여와 풍속 기여의 절댓값을 합해 최악의 부호 조합을 반영했다.','Summing absolute contributions accounts for the worst sign combination.')
add(47,(r'교재의 식 \(T=mgR/(2r^2+R^2)\)에서 R:3→3.1 cm,r:0.7→0.8 cm 변화에 따른 장력 변화를 미분으로 추정하고 증가·감소를 말하라.',r'Using the supplied formula \(T=mgR/(2r^2+R^2)\), estimate the change for R:3→3.1 cm and r:0.7→0.8 cm and decide increase/decrease.'),[r'\(T_R=mg(2r^2-R^2)/(2r^2+R^2)^2\), \(T_r=-4mgRr/(2r^2+R^2)^2\).',r'cm를 길이 단위로 대입하면 \(dT=mg[(-8.02)(0.1)-(8.4)(0.1)]/9.98^2\approx-0.016486mg\).'],[r'\(T_R=mg(2r^2-R^2)/(2r^2+R^2)^2\), \(T_r=-4mgRr/(2r^2+R^2)^2\).',r'Using cm as the length unit, \(dT=mg[(-8.02)(0.1)-(8.4)(0.1)]/9.98^2\approx-0.016486mg\).'],r'주어진 식의 cm 단위 계산에서 \(dT\approx-0.016486mg\); 감소.',r'For the supplied formula with lengths in cm, \(dT\approx-0.016486mg\); it decreases.','주어진 식 자체는 mg에 비해 역길이 차원이 남으므로 물리적인 장력식의 차원은 맞지 않는다. 여기서는 원문의 식을 그대로 미분했다.','The supplied formula retains an inverse-length factor relative to mg, so its dimensions do not match tension. The stated equation was differentiated as written.')
add(48,('PV=8.31T(P:kPa,V:L,T:K). V가12→12.3 L,T가310→305 K로 변할 때 압력 변화를 미분으로 추정하라.','For PV=8.31T with P in kPa,V in L,T in K, estimate pressure change as V changes12→12.3 L and T changes310→305 K.'),[r'\(P=8.31T/V\), \(dP=(8.31/V)dT-(8.31T/V^2)dV\).',r'\(dP=(8.31/12)(-5)-(8.31\cdot310/144)(0.3)\).'],[r'\(P=8.31T/V\), \(dP=(8.31/V)dT-(8.31T/V^2)dV\).',r'\(dP=(8.31/12)(-5)-(8.31\cdot310/144)(0.3)\).'],'약−8.829375 kPa.','Approximately−8.829375 kPa.','부피 증가와 온도 감소가 모두 압력을 내린다.','Both increasing volume and decreasing temperature lower pressure.')
add(49,('병렬 저항은 1/R=1/R1+1/R2+1/R3이다. R1=25Ω,R2=40Ω,R3=50Ω이며 각각 오차≤0.5%일 때 전체 저항 최대오차를 추정하라.','Parallel resistances satisfy1/R=1/R1+1/R2+1/R3. For R1=25Ω,R2=40Ω,R3=50Ω, each with error≤0.5%, estimate the maximum total-resistance error.'),[r'\(R=200/17\), \(dR=R^2\sum_i dR_i/R_i^2\).',r'\(|dR|\le0.005R^2\sum_i1/R_i=0.005R=1/17\).'],[r'\(R=200/17\), \(dR=R^2\sum_i dR_i/R_i^2\).',r'\(|dR|\le0.005R^2\sum_i1/R_i=0.005R=1/17\).'],'약1/17Ω≈0.05882Ω (0.5%).','Approximately1/17Ω≈0.05882Ω (0.5%).','모든 저항의 동일 상대오차는 합성저항에 동일 상대오차를 준다.','Equal relative perturbations in all resistors give the same relative perturbation in the equivalent resistance.')
add(50,(r'체표면적 \(S=0.1091w^{0.425}h^{0.725}\)에서 w,h의 상대오차가 각각≤2%이다. S의 최대 백분율오차를 미분으로 추정하라.',r'For body surface area \(S=0.1091w^{0.425}h^{0.725}\), each of w,h has relative error≤2%. Estimate maximum percentage error in S.'),[r'로그미분 \(dS/S=0.425\,dw/w+0.725\,dh/h\).','최대 절댓값은(0.425+0.725)×2%=2.3%.'],[r'Logarithmic differentiation gives \(dS/S=0.425\,dw/w+0.725\,dh/h\).','The largest absolute value is(0.425+0.725)×2%=2.3%.'],'약2.3%.','Approximately2.3%.','상수계수0.1091은 상대오차식에서 소거된다.','The constant factor0.1091 cancels from the relative-error equation.')
add(51,(r'BMI \(B=m/h^2\). (a) m=23 kg,h=1.10 m에서 선형근사를 구하라. (b) 질량+1 kg,키+3 cm일 때 추정값과 실제값을 비교하라.',r'For BMI \(B=m/h^2\), (a) linearize at m=23 kg,h=1.10 m; (b) compare estimated and actual BMI after +1 kg and +3 cm.'),[r'(a) \(L=2300/121+(100/121)(m-23)-(46000/1331)(h-1.10)\).',r'(b) dh=0.03 m을 넣으면 L≈18.79790. 실제값은 \(24/1.13^2\approx18.79552\).'],[r'(a) \(L=2300/121+(100/121)(m-23)-(46000/1331)(h-1.10)\).',r'(b) Using dh=0.03 m gives L≈18.79790; the actual value is \(24/1.13^2\approx18.79552\).'],r'(a) \(L=2300/121+(100/121)(m-23)-(46000/1331)(h-1.10)\). (b) 추정18.79790, 실제18.79552.',r'(a) \(L=2300/121+(100/121)(m-23)-(46000/1331)(h-1.10)\). (b) Estimate18.79790, actual18.79552.','cm를 m로 바꾸고 두 결과의 차이가 약0.00238임을 확인한다.','Convert cm to m; the estimates differ by about0.00238.',['a','b'])
add(52,(r'표면 S는 P=(2,1,3)을 지나고 \(r_1(t)=(2+3t,1-t^2,3-4t+t^2)\), \(r_2(u)=(1+u^2,2u^3-1,2u+1)\)를 포함한다. P의 접평면을 구하라.',r'A surface S through P=(2,1,3) contains \(r_1(t)=(2+3t,1-t^2,3-4t+t^2)\), \(r_2(u)=(1+u^2,2u^3-1,2u+1)\). Find its tangent plane at P.'),[r'P는 t=0,u=1에 해당한다. 접벡터는 \(r_1\prime(0)=(3,0,-4),r_2\prime(1)=(2,6,2)\).',r'외적은(24,−14,18)=2(12,−7,9)이므로 법선으로 사용한다.'],[r'P corresponds to t=0,u=1. The tangent vectors are \(r_1\prime(0)=(3,0,-4),r_2\prime(1)=(2,6,2)\).',r'The cross product is(24,−14,18)=2(12,−7,9), a normal.'],r'\(12(x-2)-7(y-1)+9(z-3)=0\).',r'\(12(x-2)-7(y-1)+9(z-3)=0\).','법선은 두 접벡터와 모두 내적0이고 P가 평면 위에 있다.','The normal is orthogonal to both tangents and P lies on the plane.')
add(53,('두 변수 함수 f가 (a,b)에서 미분 가능하면 그 점에서 연속임을 증명하라.','Prove that differentiability of a two-variable function at(a,b) implies continuity there.'),[r'미분 가능성이면 \(\Delta f=f_x(a,b)\Delta x+f_y(a,b)\Delta y+o(\sqrt{\Delta x^2+\Delta y^2})\).','변위가0으로 갈 때 고정계수의 두 선형항과 나머지항이 모두0으로 가므로 Δf→0이다.'],[r'Differentiability gives \(\Delta f=f_x(a,b)\Delta x+f_y(a,b)\Delta y+o(\sqrt{\Delta x^2+\Delta y^2})\).','As displacement tends to zero, both fixed-coefficient linear terms and the remainder tend to zero; hence Δf→0.'],'f는 (a,b)에서 연속이다.','f is continuous at(a,b).','연속성의 정의인 f(a+Δx,b+Δy)→f(a,b)를 직접 얻었다.','This is exactly the limit in the definition of continuity.')
add(54,(r'\(f(x,y)=xy/(x^2+y^2)\) (원점 제외), f(0,0)=0이다. (a) 두 원점 편도함수가 존재하지만 미분 불가능함을 보여라. (b) 두 편도함수가 원점에서 연속이지 않은 이유를 설명하라.',r'Let \(f(x,y)=xy/(x^2+y^2)\) off the origin and f(0,0)=0. (a) Show both origin partials exist but f is not differentiable. (b) Explain discontinuity of the partial derivatives there.'),['(a) 두 좌표축에서 f=0이므로 fx(0,0)=fy(0,0)=0이다. 하지만 y=x≠0에서는 f=1/2이므로 원점에서 연속이 아니며53번에 의해 미분 불가능하다.',r'(b) \(f_x=y(y^2-x^2)/(x^2+y^2)^2\), \(f_y=x(x^2-y^2)/(x^2+y^2)^2\). x=0에서 fx=1/y, y=0에서 fy=1/x로 발산한다.'],['(a) Both axis traces are zero, so fx(0,0)=fy(0,0)=0. Along y=x≠0, however,f=1/2, so f is discontinuous and therefore not differentiable by exercise53.',r'(b) \(f_x=y(y^2-x^2)/(x^2+y^2)^2\), \(f_y=x(x^2-y^2)/(x^2+y^2)^2\). Along x=0,fx=1/y; along y=0,fy=1/x, so both are unbounded near the origin.'],'(a) 편도함수는0, 미분 불가능. (b) 두 편도함수 모두 불연속.','(a) Both partials are zero, but f is not differentiable. (b) Both partials are discontinuous.','y=x의 값1/2는 원점 자체에는 적용하지 않는다.','The value1/2 along y=x excludes the origin itself.',['a','b'])
E.sort(key=lambda e:e['number']);assert [e['number'] for e in E]==list(range(1,55))
D=dict(section='14.4',source=dict(title='Calculus',edition='9',language='en',printedPages=[1019,1020,1021],pdfPages=[1056,1057,1058]),scope=dict(kind='exercise',numbers=list(range(1,55)),total=54,note=pair('전체 연습문제54문항과 모든 소문항.','All54 exercises and every subpart.')),exercises=E)
(R/'exercise-content/s14-4.json').write_text(json.dumps(D,ensure_ascii=False,indent=2)+'\n')
# Original wireframe surface/tangent plots at two zoom scales.
A=R/'exercise-content/assets';A.mkdir(exist_ok=True)
for n,(f,base,plane) in plots.items():
 fn=s.lambdify((x,y),f,'math');pn=s.lambdify((x,y),plane,'math');bx,by=map(float,base);fz=fn(bx,by);out=['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 960 480"><rect width="960" height="480" fill="white"/>',f'<text x="480" y="25" text-anchor="middle" font-family="sans-serif">Exercise14.4.{n}: surface(blue), tangent plane(orange)</text>']
 for panel,scale in enumerate([.35,.035]):
  # Same relative vertical and horizontal scale in both panels makes first-order agreement visible.
  gradnorm=math.hypot(float(s.diff(f,x).subs({x:base[0],y:base[1]})),float(s.diff(f,y).subs({x:base[0],y:base[1]})));zs=80/(scale*max(1,gradnorm))
  project=lambda xx,yy,zz:(240+panel*480+130*(xx-bx)/scale-75*(yy-by)/scale,260+35*(xx-bx)/scale+35*(yy-by)/scale-zs*(zz-fz))
  for fun,color in [(fn,'#2768ab'),(pn,'#da7e22')]:
   for i in range(11):
    c=-scale+2*scale*i/10
    for swap in [False,True]:
     pts=[]
     for j in range(51):
      d=-scale+2*scale*j/50;xx=bx+(d if swap else c);yy=by+(c if swap else d)
      try:zz=fun(xx,yy);px,py=project(xx,yy,zz)
      except (ValueError,ZeroDivisionError):continue
      pts.append(f'{px:.2f},{py:.2f}')
     out.append(f'<polyline points="{" ".join(pts)}" fill="none" stroke="{color}" stroke-width="1" opacity="0.7"/>')
  out.append(f'<text x="{240+480*panel}" y="450" text-anchor="middle" font-family="sans-serif">x,y half-width:{scale}</text>')
 out.append('</svg>');name=f's14-4-{n}.svg';(A/name).write_text('\n'.join(out));ex=next(e for e in E if e['number']==n);ex['figure']=dict(src='../exercise-content/assets/'+name,alt=pair('곡면과 접평면의 두 확대 수준 비교','Surface and tangent plane at two zoom scales'),caption=pair('파란 곡면과 주황 접평면을 같은 상대 축척에서 비교. 오른쪽은10배 확대.','Blue surface and orange tangent plane at the same relative scale; right panel is magnified10×.'))
(R/'exercise-content/s14-4.json').write_text(json.dumps(D,ensure_ascii=False,indent=2)+'\n')
print('14.4:',len(E),'cards;',len(plots),'SVGs')
